/**
 * Pins which partition each key lands on. Same-key events are handled
 * serially only because they share a partition, so a producer that hashed keys
 * differently would split a device's events across two partitions — and two
 * consumers — for as long as old and new producers run side by side.
 *
 * The fixture was generated by kafkajs 2.2.4's default partitioner.
 */

import { describe, expect, test } from 'bun:test';
import { Partitioners } from 'kafkajs';
import fixture from './partitioner.fixture.json' with { type: 'json' };

const partition = Partitioners.DefaultPartitioner();

const partitionFor = (key: string, partitionCount: number): number =>
  partition({
    topic: 'events',
    partitionMetadata: Array.from({ length: partitionCount }, (_, id) => ({
      partitionId: id,
      leader: 0,
      partitionErrorCode: 0,
      replicas: [0],
      isr: [0],
    })),
    message: { key, value: null },
  });

describe('key to partition', () => {
  test('matches the recorded kafkajs mapping for every key and partition count', () => {
    for (const [key, expected] of fixture.keys as [string, number[]][]) {
      const actual = fixture.counts.map((count) => partitionFor(key, count));
      expect({ key, partitions: actual }).toEqual({
        key,
        partitions: expected,
      });
    }
  });
});
